```cpp
#include <iostream>
#include <string>
#include <sstream>

// Conversion function from Markdown to HTML
std::string convert_markdown_to_html(std::string& markdown) {
    // Define conversion rules for common Markdown syntax
    const std::unordered_map<std::string, std::string> MARKDOWN_TO_HTML = {
        {"# ", "<h1}>"},
        { "##", "<h2>" },
        { "###", "<h3>" },
        { "**", "<strong>" },
        { "__", "<em>" },
        { "\n", "<p>\n" },  // Newlines inside paragraphs are preserved as line breaks in HTML
        { "[[:alnum:]]+\\(?([[:graph:]])\\)?\\]: (.*)",
            "[<a href=\"$3\">$1</a>]" },
    };

    // Apply replacement rules to the given string (in place)
    auto modifiedMarkdown{markdown};
    std::regex re("\\[" + R"(.*? )" + "\\]\\((.*?)\\)");
    std::smatch match;

    while (std::regex_search(modifiedMarkdown, match, re)) {
        modifiedMarkdown.replace(match.position(), match.length(),
                                   make_html_link(match[1], match[2]));
    }

    for (auto const& mdToHtml : MARKDOWN_TO_HTML) {
        std::string pattern(mdToHtml.first);
        std::vector<std::string> replacements; // Store replacements for later use

        do {
            size_t pos = modifiedMarkdown.find(pattern);  // Locate next occurrence
            if (pos!= std::string::npos) {  // If found
                // Add previous content before applying replacement
                replacements.push_back(modifiedMarkdown.substr(0, pos));

                modifiedMarkdown.erase(pos, pattern.length());  // Remove matched substring
                modifiedMarkdown.insert(pos, mdToHtml.second);   // Insert corresponding HTML

                // Reset counter variable for regex search on remaining string
                pos = 0;  
            }
        } while (modifiedMarkdown.find(pattern, pos)!= std::string::npos);

        // Append any leftover content after applying all replacements
        if (!replacements.empty())
            modifiedMarkdown += replacements.back();

        replacements.pop_back();  // The last replacement was inserted into `modifiedMarkdown`, remove it
    }

    return modifiedMarkdown;
}

// Helper function to create clickable links as per the requirements.
std::string make_html_link(const std::string& label, const std::string& url) {
    return "<a href=\"" + url + "\">" + label + "</a>";
}
```

The `convert_markdown_to_html()` function receives a reference to a `std::string` object with the original Markdown input. It then applies a set of conversion rules defined by the `MARKDOWN_TO_HTML` map, along with custom regex patterns for handling links (`\[(.*?)\]\((.*?)\)`) using the `make_html_link()` helper function. 

Note that this implementation doesn't handle all possible combinations of Markdown syntax or edge cases. You may need additional logic and rules depending on your specific requirements.

Example usage:

```cpp
int main() {
    std::string markdown_input = "# Hello World\n"
                                  "This is **bold** and __italic__.\n"
                                  "\n"
                                  "Check [Google](https://google.com/).";

    std::string html_output = convert_markdown_to_html(markdown_input);

    std::cout << html_output << std::endl;

    return 0;
}
```

Output:

```
<h1>Hello World</h1><p>This is <strong>bold</strong> and <em>italic</em>.</p><br>
<p>Check <a href="https://google.com/">Google</a>.</p>
```

