To integrate sentiment analysis capabilities into a Next.js application, you can utilize existing NLP libraries such as Natural Language Toolkit (NLTK) and Sentiment Analysis API services like IBM Watson, Google Cloud Natural Language API, or Azure Cognitive Services.

1. Install necessary dependencies:
   ```bash
   npm install express next nodemon cors dotenv axios
   ```

2. Create an `.env` file and insert credentials from your chosen API service provider:

   Example for IBM Watson:

   ```bash
   WATSON_API_KEY=<your_watson_api_key>
   ```

3. Initialize `server.js`, which will handle requests for sentiment analysis:

   ```javascript
   import express, { Application } from 'express';
   import { v4 as uuidv4 } from 'uuid';

   import { createClient } from '@watson-studio/natural-language-understanding';

   const PORT = process.env.PORT || 3000;

   const app: Application = express();

   // Ensure environment variables are set prior to execution
   if (!process.env.WATSON_API_KEY) {
     console.error('Watson API key not found.');
     process.exit(1);
   }

   const naturalLanguageUnderstandingClient = createClient({
     iam_apikey: <YOUR_WATSON_API_KEY>,
     version: '2021-08-01',
   });

   app.post('/analyze-sentiment', async (req, res) => {

     try {
       const analysisParams = {
         text: req.body.text,
         features: [{sentiment: {documentToneOptions: {model: 'emotion'}} }],
       };

       const { results } = await naturalLanguageUnderstandingClient.analyze(
           analysisParams
       ).catch((err) => {
          throw err;
       });

        const { document_tone: sentimentScores } = results[0];

        const polarityScore = sentimentScores.tones.find(
           ({ score: { value }) => value === 'positive').score.value - 
             sentimentScores.tones.find(({ score: { value }}) => value === 'negative').score.value;

         res.json({ polarityScore });

     } catch(err) {
       console.error(err.message);
       res.status(500).json({ message: 'Internal server error' });
     }
   });

   export default app;

   app.listen(PORT, () =>
     console.log(`Server running on http://localhost:${PORT}`)
   );
   ```

4. In your Next.js application, add a new page called e.g., `analysis.tsx`. This page would receive user input/text and send it to our server (`server.js`) via an Axios request:

   ```typescript
   import React, { useState } from'react';
   import Head from 'next/head';
   import styles from '../styles/Home.module.css';
   import axios from 'axios';

   export default function Analysis() {
     const [textValue, setTextValue] = useState('');
     const [polarityScore, setPolarityScore] = useState<number>(null);

     const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
       e.preventDefault();
       try {
         const response = await axios.post(process.env.NEXT_PUBLIC_ANALYSIS_URL + '/analyze-sentiment', {
           text: textValue,
         });

         setPolarityScore(response.data.polarityScore);
       } catch (error) {
         console.error(error);
       }
     };

     return (
       <div className={styles.container}>
         <Head>
           <title>NextJS Sentiment Analysis</title>
         </Head>

         <main>
           <h1 className={styles.title}>Sentiment Analysis</h1>

           <form onSubmit={handleSubmit} className={styles.form}>
             <label htmlFor="inputText">Enter some sample text:</label>
             <textarea
               name="inputText"
               id="inputText"
               value={textValue}
               onChange={(e) => setTextValue(e.target.value)}
               className={styles.input}
             />

             <button type="submit" className={styles.button}>
               Analyze Sentiment
             </button>
           </form>

           <div>
             {polarityScore? (
               <span>
                 Polarity Score: {Math.round(polarityScore * 100)}%
               </span>
             ) : null}
           </div>

           {/* Additional UI components for showcasing sentiment classification result */}
         </main>
       </div>
     );
   }

   export const getStaticProps = async () => {
     return {
       props: {},
     };
   };
   ```

5. Modify `package.json` to enable auto-restarting on changes:

   ```json
   "scripts": {
     "dev": "nodemon server.js",
     "build": "next build && nx run microservices:clean && nx run microservices:build",
     "start": "cross-env NODE_ENV=production node server.js"
   },
   ```

6. Set the `process.env.NEXT_PUBLIC_ANALYSIS_URL` variable in `pages/_app/server.tsx`:

   ```typescript
