```c++
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int countWord(string filename, string word) {
    int count = 0;

    // Open the specified file
    ifstream infile(filename);

    if (!infile.is_open()) {
        cerr << "Error: cannot open the file." << endl;
        return -1;   // Return error code (-1)
    }

    while (infile.good()) {   // Loop until end-of-file reached
        string line;

        getline(infile, line);   // Read one line at a time from the file

        size_t pos = line.find(word);            // Search for the target word in current line

        while (pos!= string::npos) {             // Check if the target substring is present multiple times

            ++count;                              // Increment the count whenever a match is found
            pos += word.length();                 // Update position to search again starting just past the matched substring

            pos = line.find(word, pos);           // Continue searching for the next occurrence of the target word
        }
    }

    infile.close();   // Close the input file stream

    return count;     // Return the final count of word occurrences
}

int main() {
    string filename, word;

    cout << "Enter the name of the input file: ";
    cin >> filename;

    cout << "Enter the word you want to count: ";
    cin >> word;

    auto result = countWord(filename, word);

    if (result >= 0) {
        cout << "Total occurrences of \"" << word << "\" in " << filename << ": " << result << endl;
    }

    return 0;
}
